// ─── APP STATE ───────────────────────────────────────────────
const state = {
  section: 'dashboard',
  page: 1,
  perPage: 25,
  sortKey: 'total',
  sortDir: 'desc',
  filters: {
    search: '',
    jabatan: '',
    jenis: '',
    pendidikan: '',
    keterangan: '',
  },
  modal: null,
};

// ─── UTILS ───────────────────────────────────────────────────
function fmt(n) { return n.toLocaleString('id-ID'); }
function cap(s) { return s ? s.charAt(0).toUpperCase() + s.slice(1).toLowerCase() : ''; }

function ketBadge(k) {
  if (k === 'P/L') return `<span class="badge badge-pl">⭐ P/L</span>`;
  if (k === 'P')   return `<span class="badge badge-p">✓ Lulus</span>`;
  if (k === 'TL')  return `<span class="badge badge-tl">✗ TL</span>`;
  return `<span class="badge" style="background:rgba(255,255,255,0.05);color:#64748b">${k}</span>`;
}
function jenisBadge(j) {
  if (!j) return '';
  if (j.toUpperCase().includes('UMUM')) return `<span class="badge badge-umum">UMUM</span>`;
  return `<span class="badge badge-khusus">${j}</span>`;
}

function scoreColor(val, max=200) {
  const pct = val/max;
  if (pct >= 0.8) return '#34d399';
  if (pct >= 0.6) return '#38bdf8';
  if (pct >= 0.4) return '#fbbf24';
  return '#f87171';
}
function totalColor(val) {
  if (val >= 430) return '#34d399';
  if (val >= 350) return '#38bdf8';
  if (val >= 300) return '#fbbf24';
  return '#f87171';
}

function highlight(text, search) {
  if (!search || !text) return text || '';
  const re = new RegExp(`(${search.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')})`, 'gi');
  return String(text).replace(re, '<mark class="highlight">$1</mark>');
}

// ─── FILTER & SORT ───────────────────────────────────────────
function getFiltered() {
  const {search, jabatan, jenis, pendidikan, keterangan} = state.filters;
  let res = SKD_DATA;
  if (search) {
    const q = search.toLowerCase();
    res = res.filter(r =>
      r.nama.toLowerCase().includes(q) ||
      r.no_peserta.includes(q) ||
      r.jabatan.toLowerCase().includes(q)
    );
  }
  if (jabatan) res = res.filter(r => r.jabatan === jabatan);
  if (jenis)   res = res.filter(r => r.jenis === jenis);
  if (pendidikan) res = res.filter(r => r.pendidikan.includes(pendidikan));
  if (keterangan) res = res.filter(r => r.keterangan === keterangan);

  const k = state.sortKey, dir = state.sortDir;
  res = [...res].sort((a,b) => {
    let av = a[k], bv = b[k];
    if (typeof av === 'string') av = av.toLowerCase();
    if (typeof bv === 'string') bv = bv.toLowerCase();
    if (av < bv) return dir==='asc' ? -1 : 1;
    if (av > bv) return dir==='asc' ? 1 : -1;
    return 0;
  });
  return res;
}

// ─── SECTION: DASHBOARD ──────────────────────────────────────
function renderDashboard() {
  const total = SKD_DATA.length;
  const pl = SKD_DATA.filter(r=>r.keterangan==='P/L').length;
  const p  = SKD_DATA.filter(r=>r.keterangan==='P').length;
  const tl = SKD_DATA.filter(r=>r.keterangan==='TL').length;
  const lulus = pl + p;
  const avgTotal = Math.round(SKD_DATA.reduce((s,r)=>s+r.total,0)/total);

  // Stats
  document.getElementById('stat-total').textContent = fmt(total);
  document.getElementById('stat-jabatan').textContent = fmt(JABATAN_DATA.length);
  document.getElementById('stat-lulus').textContent = fmt(lulus);
  document.getElementById('stat-avg').textContent = avgTotal;

  // Chart 1: Keterangan donut
  renderDonut();

  // Chart 2: Top jabatan by peserta
  renderTopJabatan();

  // Chart 3: Score distribution
  renderScoreDist();

  // Chart 4: Pendidikan breakdown
  renderPendidikanChart();
}

function renderDonut() {
  const pl = SKD_DATA.filter(r=>r.keterangan==='P/L').length;
  const p  = SKD_DATA.filter(r=>r.keterangan==='P').length;
  const tl = SKD_DATA.filter(r=>r.keterangan==='TL').length;
  const total = SKD_DATA.length;

  const items = [
    {label:'Prioritas Lulus (P/L)', count:pl, color:'#34d399'},
    {label:'Lulus (P)', count:p, color:'#38bdf8'},
    {label:'Tidak Lulus (TL)', count:tl, color:'#f87171'},
  ];

  const R=70, cx=90, cy=90, stroke=22;
  const circ = 2*Math.PI*R;
  let offset=0;
  let paths='';
  items.forEach(item=>{
    const pct=item.count/total;
    const dash=circ*pct;
    paths+=`<circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="${item.color}"
      stroke-width="${stroke}" stroke-dasharray="${dash.toFixed(2)} ${(circ-dash).toFixed(2)}"
      stroke-dashoffset="${(-offset).toFixed(2)}" stroke-linecap="butt"
      style="transition:stroke-dasharray 0.6s ease"/>`;
    offset+=dash;
  });

  const svg=`<svg class="donut-svg" width="180" height="180" viewBox="0 0 180 180">
    <circle cx="${cx}" cy="${cy}" r="${R}" fill="none" stroke="rgba(255,255,255,0.06)" stroke-width="${stroke}"/>
    ${paths}
    <text x="${cx}" y="${cy-8}" text-anchor="middle" font-size="22" font-weight="800" fill="#f1f5f9" font-family="JetBrains Mono,monospace">${fmt(pl+p)}</text>
    <text x="${cx}" y="${cy+10}" text-anchor="middle" font-size="10" fill="#94a3b8">LULUS</text>
  </svg>`;

  const legend=items.map(item=>`
    <div class="donut-item">
      <div class="donut-dot" style="background:${item.color}"></div>
      <span class="donut-label">${item.label}</span>
      <span class="donut-count" style="color:${item.color}">${fmt(item.count)}</span>
    </div>`).join('');

  document.getElementById('chart-donut').innerHTML=`<div class="donut-wrap">${svg}<div class="donut-legend">${legend}</div></div>`;
}

function renderTopJabatan() {
  const counts={};
  SKD_DATA.forEach(r=>{ counts[r.jabatan]=(counts[r.jabatan]||0)+1; });
  const sorted=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,8);
  const max=sorted[0][1];

  const colors=['#38bdf8','#818cf8','#34d399','#fbbf24','#c084fc','#f87171','#2dd4bf','#fb923c'];
  const html=sorted.map(([name,cnt],i)=>`
    <div class="bar-item">
      <div class="bar-item-header">
        <span class="bar-item-name">${name.length>38?name.slice(0,38)+'…':name}</span>
        <span class="bar-item-val">${fmt(cnt)}</span>
      </div>
      <div class="bar-track">
        <div class="bar-fill" style="width:${(cnt/max*100).toFixed(1)}%;background:${colors[i%colors.length]}"></div>
      </div>
    </div>`).join('');
  document.getElementById('chart-jabatan').innerHTML=`<div class="bar-chart">${html}</div>`;
}

function renderScoreDist() {
  const buckets=[
    {label:'400-500',min:400,max:500},
    {label:'350-399',min:350,max:399},
    {label:'300-349',min:300,max:349},
    {label:'250-299',min:250,max:299},
    {label:'<250',min:0,max:249},
  ];
  const counts=buckets.map(b=>{
    return {...b, cnt: SKD_DATA.filter(r=>r.total>=b.min&&r.total<=b.max).length};
  });
  const max=Math.max(...counts.map(c=>c.cnt));
  const colors=['#34d399','#38bdf8','#818cf8','#fbbf24','#f87171'];

  const html=counts.map((c,i)=>`
    <div class="dist-item">
      <span class="dist-label">${c.label}</span>
      <div class="dist-track">
        <div class="dist-fill" style="width:${(c.cnt/max*100).toFixed(1)}%;background:${colors[i]}">
          ${c.cnt>0?`<span class="dist-fill-text">${c.cnt}</span>`:''}
        </div>
      </div>
      <span class="dist-count">${fmt(c.cnt)}</span>
    </div>`).join('');
  document.getElementById('chart-dist').innerHTML=`<div class="score-dist">${html}</div>`;
}

function renderPendidikanChart() {
  const counts={};
  SKD_DATA.forEach(r=>{
    const p=r.pendidikan||'Tidak Diketahui';
    counts[p]=(counts[p]||0)+1;
  });
  const sorted=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,8);
  const max=sorted[0][1];
  const colors=['#c084fc','#34d399','#38bdf8','#fbbf24','#818cf8','#f87171','#2dd4bf','#fb923c'];
  const html=sorted.map(([name,cnt],i)=>`
    <div class="bar-item">
      <div class="bar-item-header">
        <span class="bar-item-name">${name}</span>
        <span class="bar-item-val">${fmt(cnt)}</span>
      </div>
      <div class="bar-track">
        <div class="bar-fill" style="width:${(cnt/max*100).toFixed(1)}%;background:${colors[i%colors.length]}"></div>
      </div>
    </div>`).join('');
  document.getElementById('chart-pendidikan').innerHTML=`<div class="bar-chart">${html}</div>`;
}

// ─── SECTION: REKAP (TABLE) ───────────────────────────────────
function renderRekap() {
  populateFilters();
  renderTable();
}

function populateFilters() {
  // Jabatan dropdown
  const jabList=[...new Set(SKD_DATA.map(r=>r.jabatan))].sort();
  const sel=document.getElementById('filter-jabatan');
  sel.innerHTML='<option value="">Semua Jabatan</option>'+jabList.map(j=>`<option value="${j}" ${state.filters.jabatan===j?'selected':''}>${j}</option>`).join('');

  // Jenis
  const jenList=[...new Set(SKD_DATA.map(r=>r.jenis))].sort();
  const selJ=document.getElementById('filter-jenis');
  selJ.innerHTML='<option value="">Semua Jenis</option>'+jenList.map(j=>`<option value="${j}" ${state.filters.jenis===j?'selected':''}>${j}</option>`).join('');

  // Pendidikan
  const penList=[...new Set(SKD_DATA.map(r=>r.pendidikan))].sort();
  const selP=document.getElementById('filter-pendidikan');
  selP.innerHTML='<option value="">Semua Pendidikan</option>'+penList.map(p=>`<option value="${p}" ${state.filters.pendidikan===p?'selected':''}>${p}</option>`).join('');
}

function renderTable() {
  const filtered=getFiltered();
  const total=filtered.length;
  const pages=Math.ceil(total/state.perPage);
  if (state.page>pages) state.page=Math.max(1,pages);
  const start=(state.page-1)*state.perPage;
  const rows=filtered.slice(start, start+state.perPage);
  const search=state.filters.search;

  document.getElementById('table-count').textContent=`${fmt(total)} peserta ditemukan`;

  const cols=[
    {key:'no',label:'No',w:'48px'},
    {key:'no_peserta',label:'No Peserta',w:'160px'},
    {key:'nama',label:'Nama'},
    {key:'jabatan',label:'Jabatan Formasi'},
    {key:'pendidikan',label:'Pendidikan',w:'140px'},
    {key:'tahun_skd',label:'Thn',w:'60px'},
    {key:'twk',label:'TWK',w:'80px'},
    {key:'tiu',label:'TIU',w:'80px'},
    {key:'tkp',label:'TKP',w:'80px'},
    {key:'total',label:'Total',w:'80px'},
    {key:'keterangan',label:'Ket.',w:'100px'},
  ];

  const thead=`<thead><tr>${cols.map(c=>{
    const sorted=state.sortKey===c.key;
    const icon=sorted?(state.sortDir==='asc'?'↑':'↓'):'↕';
    return `<th data-sort="${c.key}" class="${sorted?'sorted':''}" style="${c.w?`width:${c.w}`:''}">${c.label} <span class="sort-icon">${icon}</span></th>`;
  }).join('')}</tr></thead>`;

  const MAX_TWK=150, MAX_TIU=175, MAX_TKP=225;
  const tbody=rows.length===0
    ? `<tbody><tr><td colspan="${cols.length}"><div class="empty-state"><div class="empty-icon">🔍</div><div class="empty-text">Tidak ada data yang cocok</div></div></td></tr></tbody>`
    : `<tbody>${rows.map((r,i)=>{
        const twkPct=(r.twk/MAX_TWK*100).toFixed(0);
        const tiuPct=(r.tiu/MAX_TIU*100).toFixed(0);
        const tkpPct=(r.tkp/MAX_TKP*100).toFixed(0);
        return `<tr style="cursor:pointer" onclick="openModal(${JSON.stringify(r).replace(/"/g,'&quot;')})">
          <td class="td-no">${start+i+1}</td>
          <td class="td-peserta">${highlight(r.no_peserta,search)}</td>
          <td class="td-name">${highlight(r.nama,search)}</td>
          <td class="td-jabatan">${highlight(r.jabatan,search)}</td>
          <td style="font-size:11px;color:#94a3b8">${r.pendidikan}</td>
          <td style="text-align:center;font-size:12px;color:#64748b;font-family:'JetBrains Mono',monospace">${r.tahun_skd}</td>
          <td><div class="score-bar">
            <div class="score-bar-row">
              <span class="score-bar-label">TWK</span>
              <div class="score-bar-track"><div class="score-bar-fill twk" style="width:${twkPct}%"></div></div>
              <span class="score-val">${r.twk}</span>
            </div>
            <div class="score-bar-row">
              <span class="score-bar-label">TIU</span>
              <div class="score-bar-track"><div class="score-bar-fill tiu" style="width:${tiuPct}%"></div></div>
              <span class="score-val">${r.tiu}</span>
            </div>
            <div class="score-bar-row">
              <span class="score-bar-label">TKP</span>
              <div class="score-bar-track"><div class="score-bar-fill tkp" style="width:${tkpPct}%"></div></div>
              <span class="score-val">${r.tkp}</span>
            </div>
          </td>
          <td style="width:0;display:none"></td>
          <td style="width:0;display:none"></td>
          <td class="td-total" style="color:${totalColor(r.total)}">${r.total}</td>
          <td>${ketBadge(r.keterangan)}</td>
        </tr>`;
      }).join('')}</tbody>`;

  document.getElementById('skd-table').innerHTML=thead+tbody;

  // Attach sort handlers
  document.querySelectorAll('#skd-table th[data-sort]').forEach(th=>{
    th.addEventListener('click',()=>{
      const k=th.dataset.sort;
      if (state.sortKey===k) state.sortDir=state.sortDir==='asc'?'desc':'asc';
      else { state.sortKey=k; state.sortDir='desc'; }
      state.page=1;
      renderTable();
    });
  });

  renderPagination(total, pages);
}

function renderPagination(total, pages) {
  const p=state.page;
  document.getElementById('page-info').textContent=`Halaman ${p} dari ${pages} (${fmt(total)} data)`;

  const btns=[];
  btns.push(`<button class="page-btn" onclick="goPage(${p-1})" ${p<=1?'disabled':''}>‹</button>`);

  let start=Math.max(1,p-2), end=Math.min(pages,p+2);
  if (start>1) btns.push(`<button class="page-btn" onclick="goPage(1)">1</button>`);
  if (start>2) btns.push(`<span style="color:#475569;padding:0 4px">…</span>`);
  for(let i=start;i<=end;i++) {
    btns.push(`<button class="page-btn ${i===p?'active':''}" onclick="goPage(${i})">${i}</button>`);
  }
  if (end<pages-1) btns.push(`<span style="color:#475569;padding:0 4px">…</span>`);
  if (end<pages) btns.push(`<button class="page-btn" onclick="goPage(${pages})">${pages}</button>`);
  btns.push(`<button class="page-btn" onclick="goPage(${p+1})" ${p>=pages?'disabled':''}>›</button>`);

  document.getElementById('page-btns').innerHTML=btns.join('');
}

function goPage(n) {
  const filtered=getFiltered();
  const pages=Math.ceil(filtered.length/state.perPage);
  state.page=Math.max(1,Math.min(pages,n));
  renderTable();
  document.getElementById('section-rekap').scrollIntoView({behavior:'smooth',block:'start'});
}

// ─── SECTION: JABATAN ─────────────────────────────────────────
function renderJabatan() {
  const html=JABATAN_DATA.map(j=>{
    const recs=SKD_DATA.filter(r=>r.jabatan===j.jabatan);
    const pl=recs.filter(r=>r.keterangan==='P/L').length;
    const p=recs.filter(r=>r.keterangan==='P').length;
    const tl=recs.filter(r=>r.keterangan==='TL').length;
    const avg=recs.length?Math.round(recs.reduce((s,r)=>s+r.total,0)/recs.length):0;
    return `
      <div class="jabatan-card" onclick="filterByJabatan('${j.jabatan}')">
        <div class="jab-title">${j.jabatan}</div>
        <div class="jab-lokasi">📍 ${j.lokasi||'-'}</div>
        <div class="jab-meta">
          ${jenisBadge(j.jenis)}
          <span class="badge" style="background:rgba(255,255,255,0.04);color:#64748b;border:1px solid rgba(255,255,255,0.06);font-size:10px">${j.pendidikan?j.pendidikan.slice(0,40)+'…':'-'}</span>
        </div>
        <div class="jab-stats">
          <div class="jab-stat">
            <div class="jab-stat-val" style="color:#34d399">${pl+p}</div>
            <div class="jab-stat-lbl">Lulus</div>
          </div>
          <div class="jab-stat">
            <div class="jab-stat-val" style="color:#f87171">${tl}</div>
            <div class="jab-stat-lbl">TL</div>
          </div>
          <div class="jab-stat">
            <div class="jab-stat-val" style="color:#fbbf24">${avg}</div>
            <div class="jab-stat-lbl">Rata SKD</div>
          </div>
        </div>
      </div>`;
  }).join('');
  document.getElementById('jabatan-grid').innerHTML=html;
}

function filterByJabatan(jabatan) {
  state.filters.jabatan=jabatan;
  state.page=1;
  switchSection('rekap');
}

// ─── MODAL ────────────────────────────────────────────────────
function openModal(r) {
  if (typeof r==='string') r=JSON.parse(r);
  state.modal=r;
  document.getElementById('modal-name').textContent=r.nama;
  document.getElementById('modal-peserta').textContent=r.no_peserta;
  document.getElementById('modal-jabatan').textContent=r.jabatan;
  document.getElementById('modal-lokasi').textContent=r.lokasi;
  document.getElementById('modal-pendidikan').textContent=r.pendidikan;
  document.getElementById('modal-tahun').textContent=r.tahun_skd;
  document.getElementById('modal-jenis').innerHTML=jenisBadge(r.jenis);
  document.getElementById('modal-ket').innerHTML=ketBadge(r.keterangan);
  document.getElementById('modal-twk').textContent=r.twk;
  document.getElementById('modal-tiu').textContent=r.tiu;
  document.getElementById('modal-tkp').textContent=r.tkp;
  document.getElementById('modal-total').textContent=r.total;
  document.getElementById('modal-overlay').classList.add('open');
}

function closeModal() {
  document.getElementById('modal-overlay').classList.remove('open');
}

// ─── NAVIGATION ───────────────────────────────────────────────
function switchSection(name) {
  state.section=name;
  document.querySelectorAll('.section').forEach(s=>s.classList.remove('active'));
  document.querySelectorAll('.nav-btn').forEach(b=>b.classList.remove('active'));
  document.getElementById(`section-${name}`).classList.add('active');
  document.querySelector(`[data-nav="${name}"]`).classList.add('active');

  if (name==='dashboard') renderDashboard();
  else if (name==='rekap') renderRekap();
  else if (name==='jabatan') renderJabatan();
}

// ─── INIT ─────────────────────────────────────────────────────
document.addEventListener('DOMContentLoaded', () => {
  // Nav
  document.querySelectorAll('[data-nav]').forEach(btn=>{
    btn.addEventListener('click',()=>switchSection(btn.dataset.nav));
  });

  // Search
  const searchInput=document.getElementById('filter-search');
  let searchTimer;
  searchInput.addEventListener('input',()=>{
    clearTimeout(searchTimer);
    searchTimer=setTimeout(()=>{
      state.filters.search=searchInput.value.trim();
      state.page=1;
      renderTable();
    },300);
  });

  // Filters
  ['filter-jabatan','filter-jenis','filter-pendidikan','filter-keterangan'].forEach(id=>{
    document.getElementById(id).addEventListener('change',e=>{
      const key=id.replace('filter-','');
      state.filters[key]=e.target.value;
      state.page=1;
      renderTable();
    });
  });

  // Reset
  document.getElementById('btn-reset').addEventListener('click',()=>{
    state.filters={search:'',jabatan:'',jenis:'',pendidikan:'',keterangan:''};
    state.page=1;
    document.getElementById('filter-search').value='';
    document.getElementById('filter-jabatan').value='';
    document.getElementById('filter-jenis').value='';
    document.getElementById('filter-pendidikan').value='';
    document.getElementById('filter-keterangan').value='';
    renderTable();
  });

  // Modal close
  document.getElementById('modal-overlay').addEventListener('click',e=>{
    if(e.target===document.getElementById('modal-overlay')) closeModal();
  });
  document.getElementById('modal-close').addEventListener('click',closeModal);
  document.addEventListener('keydown',e=>{ if(e.key==='Escape') closeModal(); });

  // Export CSV
  document.getElementById('btn-export').addEventListener('click',()=>{
    const filtered=getFiltered();
    const cols=['no_peserta','nama','jabatan','lokasi','jenis','pendidikan','tahun_skd','twk','tiu','tkp','total','keterangan'];
    const header=cols.join(',');
    const rows=filtered.map(r=>cols.map(c=>{
      const v=String(r[c]||'');
      return v.includes(',')||v.includes('"')?`"${v.replace(/"/g,'""')}"`:v;
    }).join(','));
    const csv=header+'\n'+rows.join('\n');
    const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');
    a.href=url; a.download='SKD_Semarang_2024.csv';
    a.click(); URL.revokeObjectURL(url);
  });

  // Init
  switchSection('dashboard');
});